using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

namespace McpServer;

[McpServerToolType]
public static class ApiTools
{
    [McpServerTool, Description("Fetches data from an external API for the given resource path.")]
    public static async Task<string> FetchApiData(
        IHttpClientFactory httpClientFactory,
        [Description("Relative path of the API resource (e.g. \"users/1\").")] string resourcePath,
        CancellationToken cancellationToken = default)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");
        var response = await client.GetAsync(resourcePath, cancellationToken);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadAsStringAsync(cancellationToken);

        // Pretty-print for readability in MCP responses.
        using var doc = JsonDocument.Parse(json);
        return JsonSerializer.Serialize(doc, new JsonSerializerOptions { WriteIndented = true });
    }
}

using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpServer;

[McpServerPromptType]
public static class SummarizationPrompts
{
    [McpServerPrompt, Description("Generates a prompt that asks the model to summarize the given text.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text to summarize.")] string text,
        [Description("Desired summary style: brief, detailed, or bullet-points.")] string style = "brief")
    {
        return
        [
            new PromptMessage
            {
                Role = Role.User,
                Content = new Content
                {
                    Type = "text",
                    Text = $"""
                        Please summarize the following text in a {style} style.

                        --- BEGIN TEXT ---
                        {text}
                        --- END TEXT ---
                        """
                }
            }
        ];
    }
}

