public static class SummarizationPrompts
{
    [McpServerPrompt, Description("Generates a prompt that asks the model to summarize the given text.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text to summarize.")] string text,
        [Description("Desired summary style: brief, detailed, or bullet-points.")] string style = "brief")
    {
        return
        [
            new PromptMessage
            {
                Role = Role.User,
                Content = new Content
                {
                    Type = "text",
                    Text = $"""
                        Please summarize the following text in a {style} style.

                        --- BEGIN TEXT ---
                        {text}
                        --- END TEXT ---
                        """
                }
            }
        ];
    }
}"}

